schema_ddl:
CREATE TABLE corriere (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_azienda TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE,
    telefono TEXT
);

CREATE TABLE spedizioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_spedizione TEXT NOT NULL UNIQUE,
    corriere_id INT NOT NULL REFERENCES corriere(id),
    peso_kg NUMERIC(8,2) NOT NULL CHECK (peso_kg > 0),
    data_affidamento DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE colli (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    spedizione_id INT NOT NULL REFERENCES spedizioni(id) ON DELETE CASCADE,
    codice_collo TEXT NOT NULL UNIQUE,
    descrizione_contenuto TEXT,
    valore_dichiarato NUMERIC(10,2) CHECK (valore_dichiarato >= 0)
);
